    Array.isArray(xs) || typeof xs === 'string',
    typeMismatch('[a] -> a', [getType(xs), 'a'].join(' -> '), 'head'),
  );

  return xs[0];
};

const last = function last(xs) {
  assert(
    Array.isArray(xs) || typeof xs === 'string',
    typeMismatch('[a] -> a', [getType(xs), 'a'].join(' -> '), 'last'),
  );

