const reduce = curry(function reduce(fn, zero, xs) {
  assert(
    typeof fn === 'function' && Array.isArray(xs),
    typeMismatch('(b -> a -> b) -> b -> [a] -> b', [getType(fn), getType(zero), getType(xs), 'b'].join(' -> '), 'reduce'),
  );

