const prop = curry(function prop(p, obj) {
  assert(
    typeof p === 'string' && typeof obj === 'object' && obj !== null,
    typeMismatch('String -> Object -> a', [getType(p), getType(obj), 'a'].join(' -> '), 'prop'),
