/* eslint-enable no-param-reassign */


const typeMismatch = (src, got, fn) => `Type Mismatch in function '${fn}'

        ${fn} :: ${got}

      instead of

        ${fn} :: ${src}`;


const capitalize = s => `${s[0].toUpperCase()}${s.substring(1)}`;


